/* @lc app=leetcode id=3568 lang=kotlin */ class Solution { fun minMoves(classroom: Array<String>, energy: Int): Int = classroom.size.let { m -> classroom[0].length.let { n -> IntArray(m * n) { -1 }.let { lid -> (0 until m * n).filter { classroom[it / n][it % n] == 'L' }.forEachIndexed { b, c -> lid[c] = b }.let { (0 until m * n).count { lid[it] >= 0 }.let { cnt -> (0 until m * n).first { classroom[it / n][it % n] == 'S' }.let { s0 -> BooleanArray(m * n * 1024 * (energy + 1)).let { vis -> ((s0 * 1024) * (energy + 1) + energy).let { st0 -> vis.set(st0, true).let { generateSequence(listOf(st0) to 0) { (f, d) -> if (f.isEmpty()) null else f.flatMap { st -> (st % (energy + 1)).let { e -> (st / (energy + 1)).let { rest -> (rest % 1024).let { mask -> (rest / 1024).let { c -> if (e == 0) listOf() else listOf(c / n + 1 to c % n, c / n - 1 to c % n, c / n to c % n + 1, c / n to c % n - 1).filter { (a, b) -> a in 0 until m && b in 0 until n && classroom[a][b] != 'X' }.map { (a, b) -> (a * n + b).let { nc -> (if (lid[nc] >= 0) mask or (1 shl lid[nc]) else mask).let { nm -> ((nc * 1024 + nm) * (energy + 1) + (if (classroom[a][b] == 'R') energy else e - 1)) } } } } } } } }.filter { !vis[it] && true.also { _ -> vis[it] = true } } to d + 1 } }.firstOrNull { (f, _) -> f.any { (it / (energy + 1)) % 1024 == (1 shl cnt) - 1 } }?.second ?: -1 } } } } } } } } }